      if (n < 1) { x = vm->last_n; lo = 0; hi = 0; }
      else if (n == 1) { x = vals[0]; lo = 0; hi = 0; }
      else if (n == 2) { x = vals[0]; lo = vals[1]; hi = vals[1]; }
      else { x = vals[0]; lo = vals[1]; hi = vals[2]; }
      if (lo > hi) { long t = lo; lo = hi; hi = t; }
      out = (x >= lo && x <= hi) ? 1L : 0L;
