      var_set_num(vm, "OK", 1);
      if (is_lcm) {
        var_set_num(vm, "LCM", out);
      } else {
        var_set_num(vm, "GCD", out);
      }
      snprintf(buf, sizeof buf, "%ld", out);
      var_set_str(vm, "LAST", buf);
      snprintf(vm->last_str, sizeof vm->last_str, "%s", buf);
      bump(vm); return 1;
