      if (resolve_str_arg(vm, L, sep, sizeof sep) != 0) sep[0] = 0;
      if (L->cur.kind == TK_NUM || L->cur.kind == TK_LPAREN ||
          L->cur.kind == TK_MINUS || L->cur.kind == TK_IDENT)
        want = parse_expr(vm, L);
