      sn = strlen(sep);
      if (bag[0]) {
        p = bag;
        while (*p) {
          start = p;
          while (*p && *p != '\n') p++;
          flen = (size_t)(p - start);
          if (flen > 0) {
            size_t take = flen;
            keys++;
            if (take >= sizeof field) take = sizeof field - 1;
            memcpy(field, start, take);
            field[take] = 0;
            if (n < 256) {
              const char *rhs = field;
              char *end = 0;
              long v;
              if (sn > 0) {
                const char *sp = strstr(field, sep);
                if (sp) rhs = sp + sn;
                else rhs = NULL;
              }
              if (rhs) {
                v = strtol(rhs, &end, 10);
                if (end != rhs) {
                  while (end && *end && (*end == ' ' || *end == '\t' || *end == '\r'))
                    end++;
                  if (end && *end == 0)
                    vals[n++] = v;
                }
              }
            }
          }
          if (*p == '\n') p++;
        }
      }
